import React, { useState } from "react";
import { Link } from "react-router-dom";
import {
  initialLists,
  CURRENT_USER_ID,
  CURRENT_USER_NAME,
} from "../data/mockData";

function ShoppingListPage() {
  // Stav pro ukládání seznamů (začínáme s daty z mockData)
  const [lists, setLists] = useState(initialLists);
  // Stav pro přepínání mezi aktivními a archivovanými
  const [showArchived, setShowArchived] = useState(false);

  // Funkce pro vytvoření nového seznamu
  const handleCreateList = () => {
    const newListName = prompt("Zadejte název nového seznamu:", "Nový seznam");
    if (newListName) {
      const newList = {
        id: `list-${Date.now()}`,
        name: newListName,
        owner: CURRENT_USER_ID,
        members: [CURRENT_USER_ID],
        archived: false,
        items: [],
      };
      setLists([newList, ...lists]); // Přidáme nový seznam na začátek
    }
  };

  // Funkce pro smazání seznamu (jen vlastník)
  const handleDeleteList = (listId) => {
    if (window.confirm("Opravdu chcete smazat tento seznam?")) {
      setLists(lists.filter((list) => list.id !== listId));
    }
  };

  // Funkce pro archivaci seznamu (jen vlastník)
  const handleArchiveList = (listId) => {
    setLists(
      lists.map((list) =>
        list.id === listId ? { ...list, archived: true } : list
      )
    );
  };

  // Filtrujeme seznamy, které se mají zobrazit
  const visibleLists = lists.filter(
    (list) =>
      // Uživatel musí být členem NEBO vlastníkem
      list.members.includes(CURRENT_USER_ID) &&
      // A seznam musí odpovídat filtru (archivovaný / nearchivovaný)
      list.archived === showArchived
  );

  // Funkce pro hezčí zobrazení vlastníka
  const getOwnerName = (list) => {
    return list.owner === CURRENT_USER_ID ? CURRENT_USER_NAME : "Sarah"; // Sarah je jen příklad
  };

  return (
    <>
      <div className="header">
        <h1>🛒 Shopping lists</h1>
        <button className="button-primary" onClick={handleCreateList}>
          + Create new list
        </button>
      </div>

      <div className="tabs">
        <button
          className={`tab-button ${!showArchived ? "active" : ""}`}
          onClick={() => setShowArchived(false)}
        >
          Active
        </button>
        <button
          className={`tab-button ${showArchived ? "active" : ""}`}
          onClick={() => setShowArchived(true)}
        >
          Archive
        </button>
      </div>

      <div className="content">
        {visibleLists.map((list) => {
          const isOwner = list.owner === CURRENT_USER_ID;
          return (
            <div key={list.id} className="list-card">
              <div className="list-card-info">
                {/* Link komponenta nás přenese na detail seznamu */}
                <Link to={`/list/${list.id}`} style={{ textDecoration: "none" }}>
                  <h3>{list.name}</h3>
                </Link>
                <p>
                  owner: {getOwnerName(list)} / members: {list.members.length}
                </p>
              </div>
              <div className="list-card-actions">
                {/* Tlačítka se zobrazí, jen pokud je uživatel vlastník */}
                {isOwner && !list.archived && (
                  <button
                    className="button-icon"
                    title="Archivovat"
                    onClick={() => handleArchiveList(list.id)}
                  >
                    🗄️
                  </button>
                )}
                {isOwner && (
                  <button
                    className="button-icon"
                    title="Smazat"
                    onClick={() => handleDeleteList(list.id)}
                  >
                    🗑️
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </>
  );
}

export default ShoppingListPage;
